const year=document.getElementById("year");if(year)year.textContent=new Date().getFullYear();const toggle=document.querySelector(".nav-toggle");const nav=document.getElementById("main-nav");if(toggle&&nav){toggle.addEventListener("click",()=>{const open=nav.classList.toggle("open");toggle.setAttribute("aria-expanded",String(open));toggle.textContent=open?"閉じる":"メニュー"});nav.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{nav.classList.remove("open");toggle.setAttribute("aria-expanded","false");toggle.textContent="メニュー"}))}
